// src/components/ui/LoanModal.js
import React, { useState, useEffect } from 'react';
import { loansAPI, clientsAPI } from '../../services/api';
import { X, Calculator } from 'lucide-react';

const fmtMoney = (n) => new Intl.NumberFormat('fr-FR').format(Math.round(n || 0)) + ' FCFA';

export default function LoanModal({ onClose, onSave }) {
  const [form, setForm] = useState({ clientId: '', amount: '', interestRate: '', duration: '' });
  const [clients, setClients] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    clientsAPI.getAll().then(r => setClients(r.data.data)).catch(() => {});
  }, []);

  const amount = parseFloat(form.amount) || 0;
  const rate = parseFloat(form.interestRate) || 0;
  const duration = parseInt(form.duration) || 0;
  const interest = amount * (rate / 100);
  const total = amount + interest;
  const monthly = duration > 0 ? Math.round(total / duration) : 0;

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      await loansAPI.create({
        clientId: form.clientId,
        amount: parseFloat(form.amount),
        interestRate: parseFloat(form.interestRate),
        duration: parseInt(form.duration),
      });
      onSave();
    } catch (err) {
      setError(err.response?.data?.message || 'Erreur');
    }
    setLoading(false);
  };

  return (
    <div className="modal-backdrop" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal fade-in" style={{ maxWidth: 520 }}>
        <div className="modal-header">
          <h3>Nouveau prêt</h3>
          <button onClick={onClose} className="btn btn-icon btn-outline"><X size={15} /></button>
        </div>
        <form onSubmit={handleSubmit}>
          <div className="modal-body">
            {error && <div className="alert alert-danger">{error}</div>}
            <div className="form-group">
              <label>Client *</label>
              <select className="form-control" value={form.clientId}
                onChange={e => setForm({ ...form, clientId: e.target.value })} required>
                <option value="">Sélectionner un client...</option>
                {clients.map(c => <option key={c._id} value={c._id}>{c.name}</option>)}
              </select>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
              <div className="form-group">
                <label>Montant (FCFA) *</label>
                <input className="form-control" type="number" min="0" value={form.amount}
                  onChange={e => setForm({ ...form, amount: e.target.value })} required placeholder="100000" />
              </div>
              <div className="form-group">
                <label>Taux d'intérêt (%) *</label>
                <input className="form-control" type="number" min="0" max="100" step="0.1" value={form.interestRate}
                  onChange={e => setForm({ ...form, interestRate: e.target.value })} required placeholder="10" />
              </div>
            </div>
            <div className="form-group">
              <label>Durée (mois) *</label>
              <input className="form-control" type="number" min="1" value={form.duration}
                onChange={e => setForm({ ...form, duration: e.target.value })} required placeholder="12" />
            </div>

            {/* Preview */}
            {amount > 0 && rate > 0 && duration > 0 && (
              <div style={{ background: 'var(--primary-subtle)', borderRadius: 10, padding: 16, marginTop: 4 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 12, fontSize: 12, fontWeight: 600, color: 'var(--primary-light)' }}>
                  <Calculator size={13} /> Calcul automatique
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                  {[
                    { label: 'Intérêt', value: fmtMoney(interest) },
                    { label: 'Total à payer', value: fmtMoney(total) },
                    { label: 'Mensualité', value: fmtMoney(monthly) },
                    { label: 'Nb. échéances', value: `${duration} mois` },
                  ].map(({ label, value }) => (
                    <div key={label} style={{ background: '#fff', borderRadius: 8, padding: '10px 12px' }}>
                      <div style={{ fontSize: 10, color: 'var(--gray-500)', textTransform: 'uppercase', fontWeight: 600, marginBottom: 2 }}>{label}</div>
                      <div style={{ fontSize: 14, fontWeight: 600, color: 'var(--primary)' }}>{value}</div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
          <div className="modal-footer">
            <button type="button" onClick={onClose} className="btn btn-outline">Annuler</button>
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Création...' : 'Créer le prêt'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
